			message := fmt.Sprintf(format, args...)
			path := strings.Join(issue.Path(), ".")
			if path != "" && !strings.Contains(message, path) {
				message = path + ": " + message
			}

			line, column, found := yamlSourcePosition(b, issue.Path(), strings.Contains(message, "field not allowed"))
			pos := issue.Position()
			if !pos.IsValid() {
				for _, inputPos := range issue.InputPositions() {
					if inputPos.IsValid() {
						pos = inputPos
						break
					}
				}
			}
			location := Location{File: file}
			if found {
				location.Line = line
				location.Column = column
			} else if pos.IsValid() {
				location.Line = pos.Line()
				location.Column = pos.Column()
			}
			result.Errors = append(result.Errors, Error{
				Field: path, Message: message, Location: location,
			})
		}
		return result, ErrValidationFailed
	}
	return Result{Errors: []Error{}}, nil
}

// yamlSourcePosition resolves a CUE data path to the corresponding YAML node.
// Unknown-field errors point at the mapping key; other errors point at the value.
func yamlSourcePosition(b []byte, path []string, keyPosition bool) (line, column int, ok bool) {
	var document stdyaml.Node
	if err := stdyaml.NewDecoder(bytes.NewReader(b)).Decode(&document); err != nil || len(document.Content) == 0 {
		return 0, 0, false
	}
	node := document.Content[0]
	for i, part := range path {
		switch node.Kind {
		case stdyaml.MappingNode:
			var value *stdyaml.Node
			for j := 0; j+1 < len(node.Content); j += 2 {
				if node.Content[j].Value == part {
					if keyPosition && i == len(path)-1 {
						return node.Content[j].Line, node.Content[j].Column, true
					}
					value = node.Content[j+1]
					break
				}
			}
			if value == nil {
				return 0, 0, false
			}
			node = value
		case stdyaml.SequenceNode:
			var index int
			if _, err := fmt.Sscanf(part, "%d", &index); err != nil || index < 0 || index >= len(node.Content) {
				return 0, 0, false
			}
			node = node.Content[index]
		default:
			return 0, 0, false
		}
	}
	return node.Line, node.Column, true
}

// ValidateBytes takes a slice of bytes and validates them against the schema.
func ValidateBytes(b []byte) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	_, err = validator.Validate("", b)
	return err
}

// validate is retained for package-level callers that need the raw CUE error.
func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)
	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}
	yv := cctx.BuildFile(f, cue.Scope(v))
	return v.Unify(yv).Validate()
}

// Location contains the source position of a validation issue.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes a validation issue and the field that caused it.
type Error struct {
	Field    string   `json:"field,omitempty"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	switch format {
	case jsonFormat:
		return json.NewEncoder(w).Encode(result)
	case textFormat:
		fmt.Fprintln(w, "Validation failed:")
	default:
		fmt.Fprintln(w, `Invalid format chosen, defaulting to "text" format...`)
		fmt.Fprintln(w, "Validation failed:")
	}

	for _, issue := range result.Errors {
		location := fmt.Sprintf("%s:%d:%d", issue.Location.File, issue.Location.Line, issue.Location.Column)
		if issue.Field != "" {
			fmt.Fprintf(w, "%s: %s: %s\n", location, issue.Field, issue.Message)
		} else {
			fmt.Fprintf(w, "%s: %s\n", location, issue.Message)
		}
	}
	return nil
}

// ValidateFiles validates each file and writes all findings in the requested format.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	result := Result{Errors: make([]Error, 0)}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			fmt.Fprintf(dst, "Failed to read file %s: %v\n", file, err)
			return ErrValidationFailed
		}
		fileResult, validationErr := validator.Validate(file, b)
		if validationErr != nil && !errors.Is(validationErr, ErrValidationFailed) {
			result.Errors = append(result.Errors, Error{Field: "", Message: validationErr.Error(), Location: Location{File: file}})
			continue
		}
		result.Errors = append(result.Errors, fileResult.Errors...)
	}
	if len(result.Errors) > 0 {
		if err := writeErrorDetails(format, result, dst); err != nil {
			return err
		}
		return ErrValidationFailed
	}
	if format == jsonFormat {
		return json.NewEncoder(dst).Encode(result)
	}
	fmt.Fprintln(dst, "✅ Validation success!")
	return nil
}
